    public void write()
    {
        FormDataSource formDs = this;
        RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
            retailPeriodicDiscountLine is GUPMarginComponentPriceAdjustmentLine)
        {
            GUPMarginComponentPriceAdjustmentLine retailPeriodicDiscount_GUPMarginComponentPriceAdjustmentLine = retailPeriodicDiscountLine;
            FormRun formRun = this.formRun();
            InventDim inventDimPriceAdjustmentLine = formRun.dataSource(formdatasourcestr(RetailPeriodicDiscount, InventDimPriceAdjustmentLine)).cursor();
            retailPeriodicDiscount_GUPMarginComponentPriceAdjustmentLine.InventDimId = InventDim::findOrCreate(inventDimPriceAdjustmentLine).inventDimId;
        }

        next write();
            
        this.reread();
    }

    public void initValue()
    {
        FormDataSource formDs = this;
        RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();

        next initValue();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
            retailPeriodicDiscountLine is GUPMarginComponentPriceAdjustmentLine)
        {
            GUPMarginComponentPriceAdjustmentLine retailPeriodicDiscount_GUPMarginComponentPriceAdjustmentLine = retailPeriodicDiscountLine;

            retailPeriodicDiscount_GUPMarginComponentPriceAdjustmentLine.UnitAppliesToAll = NoYes::Yes;
        }
    }
